import com.library.auth.entity.User; import com.library.auth.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class DataSeeder implements CommandLineRunner {private final UserRepository repo;private final PasswordEncoder encoder;public void run(String...a){seed("Quản trị hệ thống","admin@library.vn","ADMIN001",User.Role.ADMIN);seed("Thủ thư Nguyễn An","librarian@library.vn","TT001",User.Role.LIBRARIAN);seed("Độc giả Trần Minh","member@library.vn","DG001",User.Role.MEMBER);}private void seed(String n,String e,String c,User.Role r){if(!repo.existsByEmailIgnoreCase(e))repo.save(User.builder().fullName(n).email(e).password(encoder.encode("Library@123")).memberCode(c).role(r).status(User.Status.ACTIVE).build());}}

